begin;
create function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'assertion failed: %',message; end if; end $$;
insert into auth.users(id) values('28000200-0000-4000-8000-000000000001'),('28000200-0000-4000-8000-000000000002');
insert into public.user_roles(user_id,role) values('28000200-0000-4000-8000-000000000001','professional') on conflict do nothing;
insert into public.professional_student_relationships(professional_user_id,student_user_id,status) values('28000200-0000-4000-8000-000000000001','28000200-0000-4000-8000-000000000002','active');
set local role authenticated;
select set_config('request.jwt.claim.sub','28000200-0000-4000-8000-000000000001',true);
select public.save_student_plan_draft('28000200-0000-4000-8000-000000000002','Plano','{"routines":[{"id":"a","name":"A","ex":[{"id":"0043","sets":3,"reps":10,"weight":20}]}],"week":{"1":"a"}}',0);
select public.send_student_plan('28000200-0000-4000-8000-000000000002',1);
select set_config('request.jwt.claim.sub','28000200-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.athlete_plan_selection),'received plan is not selected');
select pg_temp.assert_true((select count(*)=0 from public.athlete_routines),'delivery leaves routines untouched');
select public.save_athlete_plan(0,'weekly','{"week":{"2":"28000200-0000-4000-8000-000000000010"},"dayPlan":{}}',
 '[{"id":"28000200-0000-4000-8000-000000000010","title":"Personal","prescription":{"ex":[]}}]');
select public.apply_library_plan((select (i->>'id')::uuid from jsonb_array_elements(public.athlete_plan_library_page()->'items') i where i->>'source_type'='professional'));
select pg_temp.assert_true((select prescription->>'programVersionId' is not null from public.athlete_routines where prescription->>'assigned'='true'),'active routine references published version');
select set_config('request.jwt.claim.sub','28000200-0000-4000-8000-000000000001',true);
select public.save_student_plan_draft('28000200-0000-4000-8000-000000000002','Plano','{"routines":[{"id":"a","name":"A","ex":[{"id":"0043","sets":4,"reps":8,"weight":20}]}],"week":{"1":"a"}}',1);
select public.send_student_plan('28000200-0000-4000-8000-000000000002',2);
select set_config('request.jwt.claim.sub','28000200-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select schedule->'assignedProgram'->>'versionNumber'='1' from public.athlete_schedules where user_id=auth.uid()),'update waits for confirmation');
select public.apply_library_plan((select (i->>'id')::uuid from jsonb_array_elements(public.athlete_plan_library_page()->'items') i where i->>'source_type'='professional'));
select pg_temp.assert_true((select schedule->'assignedProgram'->>'versionNumber'='2' from public.athlete_schedules where user_id=auth.uid()),'confirmed update is applied');
select public.apply_library_plan((select (i->>'id')::uuid from jsonb_array_elements(public.athlete_plan_library_page()->'items') i where i->>'source_type'='professional'));
select pg_temp.assert_true((select count(*)=1 from public.athlete_routines where prescription->>'assigned'='true'),'reapplication replaces rather than duplicates routines');
select pg_temp.assert_true((select count(*)=1 from public.athlete_routines where title='Personal'),'personal routine survives application and updates');
select pg_temp.assert_true((select s.schedule->>'libraryId'=p.plan_id::text from public.athlete_schedules s join public.athlete_plan_selection p using(user_id) where s.user_id=auth.uid()),'selection and schedule agree');
select pg_temp.assert_true((select i->'workout_updates' ? 'monday' from jsonb_array_elements(public.athlete_plan_library_page()->'items') i where i->>'source_type'='professional'),'changed day is flagged');
select public.mark_professional_plan_update_seen((select l.id from public.athlete_plan_library l join public.program_assignments a on a.id=l.assignment_id join public.program_versions v on v.id=a.version_id where l.source_type='professional' order by v.version_number desc limit 1),(select a.version_id from public.program_assignments a join public.program_versions v on v.id=a.version_id where a.student_user_id=auth.uid() order by v.version_number desc limit 1));
select pg_temp.assert_true((select i->'workout_updates'='{}' from jsonb_array_elements(public.athlete_plan_library_page()->'items') i where i->>'source_type'='professional'),'acknowledgement clears the indicator');
rollback;
